<?php $balance=(float)$plan->total_amount-(float)$plan->total_paid; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover"><title><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?> — Installment Plan</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="<?= $theme_link; ?>css/font-awesome-4.7.0/css/font-awesome.min.css"><style>:root{--p:#0057ff;--bg:#f1f5f9;--text:#0f172a;--muted:#64748b;--border:#e2e8f0;--good:#059669;--bad:#dc2626;--warn:#ea580c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,sans-serif}.screen{min-height:100vh;padding:12px 16px 160px}.topbar{align-items:center;display:flex;gap:12px;margin-bottom:16px;padding-top:calc(8px + env(safe-area-inset-top,0px))}.back{color:var(--p);font-size:20px;text-decoration:none}.titles{flex:1;min-width:0}.store{color:var(--muted);font-size:11px;font-weight:600;letter-spacing:.4px;overflow:hidden;text-overflow:ellipsis;text-transform:uppercase;white-space:nowrap}h1{font-size:21px;margin:2px 0}.summary{background:#fff;border:1px solid var(--border);border-radius:14px;margin-bottom:14px;padding:14px}.customer{font-size:16px;font-weight:700}.muted{color:var(--muted);font-size:13px;margin-top:4px}.numbers{display:grid;gap:8px;grid-template-columns:repeat(3,1fr);margin-top:14px}.number{background:var(--bg);border-radius:10px;padding:9px}.number span{color:var(--muted);display:block;font-size:10px}.number b{display:block;font-size:13px;margin-top:4px}.schedule{display:grid;gap:9px}.payment{align-items:center;background:#fff;border:1px solid var(--border);border-radius:13px;display:flex;gap:10px;padding:12px}.n{background:#eff6ff;border-radius:50%;color:var(--p);font-size:12px;font-weight:700;height:31px;line-height:31px;text-align:center;width:31px}.info{flex:1;min-width:0}.info b{font-size:14px}.info span{color:var(--muted);display:block;font-size:12px;margin-top:3px}.paid{color:var(--good);font-size:12px;font-weight:700}.overdue{color:var(--bad);font-size:12px;font-weight:700}.pay{background:var(--p);border:0;border-radius:9px;color:#fff;font:600 12px inherit;min-height:36px;padding:0 10px}.sheet{background:rgba(15,23,42,.45);bottom:0;display:none;left:0;padding:16px;position:fixed;right:0;top:0;z-index:700}.sheet.open{align-items:flex-end;display:flex}.panel{background:#fff;border-radius:20px 20px 12px 12px;padding:20px 16px calc(20px + env(safe-area-inset-bottom,0px));width:100%}.panel-head{align-items:center;display:flex;font-size:18px;font-weight:700;justify-content:space-between}.close{background:transparent;border:0;color:var(--muted);font-size:24px}label{display:block;font-size:13px;font-weight:600;margin:15px 0 6px}input,textarea{border:1px solid var(--border);border-radius:10px;font:inherit;padding:10px;width:100%}textarea{resize:vertical}.types{display:flex;flex-wrap:wrap;gap:8px}.type{background:#fff;border:1px solid var(--border);border-radius:9px;color:var(--text);font:600 13px inherit;padding:9px 12px}.type.active{background:#eff6ff;border-color:var(--p);color:var(--p)}.save{background:var(--p);border:0;border-radius:10px;color:#fff;font:600 15px inherit;margin-top:20px;min-height:46px;width:100%}</style></head><body><main class="screen"><header class="topbar"><a class="back" href="<?= base_url('mobile/installments'); ?>"><i class="fa fa-chevron-left"></i></a><div class="titles"><div class="store"><?= htmlspecialchars($SITE_TITLE ?? 'MartPoint'); ?></div><h1>Installment Plan</h1></div></header><section class="summary"><div class="customer"><?= htmlspecialchars($plan->customer_name ?: 'Customer'); ?></div><div class="muted"><?= htmlspecialchars($plan->plan_code); ?><?= $plan->mobile ? ' · '.htmlspecialchars($plan->mobile) : ''; ?></div><div class="numbers"><div class="number"><span>Total</span><b><?= mp_format_money($plan->total_amount); ?></b></div><div class="number"><span>Paid</span><b><?= mp_format_money($plan->total_paid); ?></b></div><div class="number"><span>Balance</span><b><?= mp_format_money($balance); ?></b></div></div></section><section class="schedule"><?php foreach($plan->payments as $payment): $outstanding=max(0,(float)$payment->amount_due-(float)$payment->amount_paid); ?><article class="payment"><div class="n"><?= (int)$payment->installment_number ?: 'DP'; ?></div><div class="info"><b><?= show_date($payment->due_date); ?> · <?= mp_format_money($payment->amount_due); ?></b><span><?= $payment->amount_paid > 0 ? 'Paid: '.mp_format_money($payment->amount_paid).' · ' : ''; ?><?= htmlspecialchars(ucfirst($payment->status)); ?><?= $payment->late_fee > 0 ? ' · Late fee: '.mp_format_money($payment->late_fee) : ''; ?></span></div><?php if($payment->status==='paid'): ?><span class="paid">Paid</span><?php elseif($can_pay): ?><button class="pay" type="button" data-id="<?= (int)$payment->id; ?>" data-amount="<?= number_format($outstanding,2,'.',''); ?>" data-number="<?= (int)$payment->installment_number; ?>" onclick="openPay(this)">Pay</button><?php else: ?><span class="<?= $payment->status==='overdue'?'overdue':'muted'; ?>"><?= ucfirst($payment->status); ?></span><?php endif; ?></article><?php endforeach; ?></section></main><div class="sheet" id="paySheet"><form class="panel" id="payForm"><div class="panel-head"><span>Record Payment</span><button class="close" type="button" onclick="closePay()">&times;</button></div><input id="payment_id" name="payment_id" type="hidden"><input name="<?= $this->security->get_csrf_token_name(); ?>" value="<?= $this->security->get_csrf_hash(); ?>" type="hidden"><label id="payLabel" for="amount_paid">Amount to pay</label><input id="amount_paid" name="amount_paid" min="0.01" required step="0.01" type="number"><label>Payment type</label><input id="payment_type" name="payment_type" value="Cash" type="hidden"><div class="types"><button class="type active" data-type="Cash" type="button" onclick="chooseType(this)">Cash</button><button class="type" data-type="Card" type="button" onclick="chooseType(this)">Card</button><button class="type" data-type="Transfer" type="button" onclick="chooseType(this)">Transfer</button></div><label for="payment_note">Note (optional)</label><textarea id="payment_note" name="payment_note" rows="2"></textarea><button class="save" type="submit">Record Payment</button></form></div><?php $this->load->view('mobile/bottom_nav',['active'=>'more']); ?><?php $this->load->view('mobile/mp_alert'); ?><?php $this->load->view('mobile/chat'); ?><script>var sheet=document.getElementById('paySheet'),form=document.getElementById('payForm');function openPay(b){document.getElementById('payment_id').value=b.dataset.id;document.getElementById('amount_paid').value=b.dataset.amount;document.getElementById('payLabel').textContent='Amount to pay — installment '+b.dataset.number;sheet.classList.add('open')}function closePay(){sheet.classList.remove('open')}function chooseType(b){document.querySelectorAll('.type').forEach(function(x){x.classList.remove('active')});b.classList.add('active');document.getElementById('payment_type').value=b.dataset.type}sheet.addEventListener('click',function(e){if(e.target===sheet)closePay()});form.addEventListener('submit',function(e){e.preventDefault();var button=form.querySelector('.save');button.disabled=true;button.textContent='Saving…';fetch('<?= base_url('mobile/save_installment_payment/'.(int)$plan->id); ?>',{method:'POST',body:new FormData(form),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(r.status==='success'){location.reload();return}alert(r.message||'Unable to record payment.')}).catch(function(){alert('Unable to record payment.')}).then(function(){button.disabled=false;button.textContent='Record Payment'})});</script></body></html>
